    return new Paragraph({
        heading: level,
        alignment: AlignmentType.RIGHT,
        children: [new TextRun({ text, bold: true, color: greenColor, font: 'B Nazanin', size: 28 })],
        spacing: { before: 300, after: 200 }
    });
}

function para(text, opts = {}) {
    return new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [new TextRun({ text, font: 'B Nazanin', size: 24, ...opts })],
        spacing: { after: 100 }
    });
}

function bullet(text) {
    return new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [new TextRun({ text: '• ' + text, font: 'B Nazanin', size: 24 })],
        spacing: { after: 80 }
    });
}

function cell(text, opts = {}) {
    return new TableCell({
        width: { size: opts.width || 5000, type: WidthType.DXA },
        shading: opts.shading ? { fill: opts.shading, type: ShadingType.CLEAR } : undefined,
        children: [new Paragraph({
            alignment: AlignmentType.RIGHT,
            children: [new TextRun({ text, font: 'B Nazanin', size: 22, bold: opts.bold || false })]
        })]
    });
}

function row(cells) {
    return new TableRow({ children: cells });
}

